package com.opspilot.document; import java.time.*; import com.opspilot.workspace.Workspace; import com.opspilot.user.User; import jakarta.persistence.*;
@Entity @Table(name="documents") public class Document {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="workspace_id",nullable=false) private Workspace workspace;@Column(nullable=false,length=200) private String title;@Lob @Column(nullable=false,columnDefinition="LONGTEXT") private String content;@Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private DocumentStatus status;@ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="created_by",nullable=false) private User createdBy;@Column(name="created_at",nullable=false,updatable=false) private Instant createdAt;@Column(name="updated_at",nullable=false) private Instant updatedAt;protected Document(){}public Document(Workspace w,String t,String c,User u){workspace=w;title=t;content=c;createdBy=u;status=DocumentStatus.ACTIVE;}@PrePersist void created(){Instant n=Instant.now();createdAt=n;updatedAt=n;}@PreUpdate void updated(){updatedAt=Instant.now();}public void update(String t,String c){if(t!=null)title=t;if(c!=null)content=c;}public void archive(){status=DocumentStatus.ARCHIVED;}public Long getId(){return id;}public Workspace getWorkspace(){return workspace;}public String getTitle(){return title;}public String getContent(){return content;}public DocumentStatus getStatus(){return status;}public User getCreatedBy(){return createdBy;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}}
